const payload = $json.body ?? $json;
const isMetaCloud = payload.object === 'whatsapp_business_account';
let externalId = '';
let remoteJid = '';
let phone = '';
let displayName = '';
let text = '';
let messageTypeRaw = '';
let message = {};
let isImage = false;
let isReaction = false;
let mediaReference = '';
let timestamp = Math.floor(Date.now() / 1000);
let ignored = false;

if (isMetaCloud) {
  const value = payload.entry?.[0]?.changes?.[0]?.value ?? {};
  const metaMessage = value.messages?.[0] ?? null;
  const contact = value.contacts?.[0] ?? {};
  if (!metaMessage) {
    ignored = true;
  } else {
    externalId = String(metaMessage.id ?? '');
    phone = String(metaMessage.from ?? '').replace(/\D/g, '');
    remoteJid = phone ? phone + '@s.whatsapp.net' : '';
    displayName = String(contact.profile?.name ?? '').slice(0, 120);
    messageTypeRaw = String(metaMessage.type ?? '');
    timestamp = Number(metaMessage.timestamp ?? timestamp);
    isImage = messageTypeRaw === 'image';
    if (messageTypeRaw === 'interactive') {
      text = String(
        metaMessage.interactive?.button_reply?.id
        ?? metaMessage.interactive?.button_reply?.title
        ?? metaMessage.interactive?.list_reply?.id
        ?? metaMessage.interactive?.list_reply?.title
        ?? ''
      ).trim();
    } else {
      text = String(metaMessage.text?.body ?? metaMessage.image?.caption ?? '').trim();
    }
    mediaReference = String(metaMessage.image?.id ?? (isImage ? 'meta-media:' + externalId : ''));
  }
} else {
  const data = payload.data ?? {};
  const key = data.key ?? {};
  message = data.message ?? {};
  remoteJid = String(key.remoteJid ?? data.remoteJid ?? '');
  messageTypeRaw = String(data.messageType ?? '');
  isReaction = messageTypeRaw === 'reactionMessage' || Boolean(message.reactionMessage);
  let interactiveText = '';
  try {
    const params = message.interactiveResponseMessage?.nativeFlowResponseMessage?.paramsJson;
    if (params) {
      const parsed = JSON.parse(params);
      interactiveText = String(parsed.id ?? parsed.display_text ?? parsed.text ?? parsed.button_id ?? '');
    }
  } catch {}
  text = String(
    message.conversation
    ?? message.extendedTextMessage?.text
    ?? message.imageMessage?.caption
    ?? message.buttonsResponseMessage?.selectedDisplayText
    ?? message.buttonsResponseMessage?.selectedButtonId
    ?? message.templateButtonReplyMessage?.selectedDisplayText
    ?? message.templateButtonReplyMessage?.selectedId
    ?? interactiveText
    ?? ''
  ).trim();
  isImage = messageTypeRaw === 'imageMessage' || Boolean(message.imageMessage);
  externalId = String(key.id ?? data.id ?? '');
  timestamp = Number(data.messageTimestamp ?? timestamp);
  phone = remoteJid.split('@')[0].replace(/\D/g, '');
  displayName = String(data.pushName ?? '').slice(0, 120);
  mediaReference = String(message.imageMessage?.url ?? (isImage ? 'evolution-media:' + externalId : ''));
  ignored = payload.event !== 'messages.upsert' || !externalId || Boolean(key.fromMe) || remoteJid.endsWith('@g.us') || isReaction || (!text && !isImage);
}

const simplified = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
let intent = 'other';
if (isImage) intent = 'receipt';
else if (/(^|\b)(parar|para|cancelar|cancela|sair|remover|remove|tirar|tira|nao quero|não quero)(\b|$)/.test(simplified)) intent = 'stop';
else if (/(^|\b)(copy_pix|copiar pix|copia pix|copia e cola|pix copia|codigo pix|código pix|manda o pix|envia o pix|quero o pix)(\b|$)/.test(simplified)) intent = 'copy_pix';
else if (/(^|\b)(payment_check|ja paguei|paguei|pagamento feito|fiz o pagamento|verificar pagamento|confirma pagamento|confirmar pagamento)(\b|$)/.test(simplified)) intent = 'paid_check';
else if (/^(sim|quero|pode|pode enviar|manda|envia|vou querer)$/.test(simplified)) intent = 'affirmative';
else if (/^(nao|não|agora nao|agora não)$/.test(simplified)) intent = 'negative';
else if (/(kit|matematica|matemática|comprar|adquirir|atividades)/.test(simplified)) intent = 'purchase';

ignored = ignored || !externalId || !remoteJid || (!text && !isImage);
return [{ json: {
  externalId, instance: String(payload.instance ?? (isMetaCloud ? 'meta-cloud' : '')),
  whatsappId: remoteJid, phone,
  displayName, fromMe: false,
  isGroup: remoteJid.endsWith('@g.us'), messageType: isReaction ? 'reaction' : (isImage ? 'image' : 'text'),
  text: text.slice(0, 4000), intent, ignored,
  mediaReference,
  eventAt: new Date(timestamp * 1000).toISOString()
} }];

const state = String($json.state ?? 'new');
const intent = String($json.intent ?? 'other');
const messageType = String($json.messageType ?? 'text');
const text = String($json.text ?? '').trim();
let route = 'duplicate';
if (!$json.inserted) route = 'duplicate';
else if (intent === 'stop') route = 'stop';
else if (intent === 'purchase') route = 'offer';
else if (state === 'stopped') route = 'duplicate';
else if (state === 'awaiting_consent') route = 'materials';
else if (state === 'awaiting_payment' && intent === 'paid_check') route = 'verify_payment';
else if (state === 'awaiting_payment' && intent === 'copy_pix') route = 'copy_pix';
else if (intent === 'receipt' && state === 'awaiting_payment') route = 'receipt';
else if (state === 'awaiting_payment' && messageType === 'text' && text.length > 0) route = 'payment_name';
return [{ json: { ...$json, route } }];

const fs = require('fs');
const path = require('path');
const manifestPath = '/files/manifest.json';
if (!fs.existsSync(manifestPath)) throw new Error('Copie manifest.example.json para manifest.json e configure os materiais.');
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
if (!Array.isArray(manifest.documents) || manifest.documents.length !== 9) throw new Error('O manifesto precisa conter nove PDFs.');
const base = $('Route State').item.json;
return manifest.documents.sort((a,b) => a.order - b.order).map((doc) => {
  const filePath = path.join('/files', doc.file);
  if (!fs.existsSync(filePath)) throw new Error('PDF ausente em /files: ' + doc.file);
  const documentBase64 = fs.readFileSync(filePath).toString('base64');
  return { json: { ...base, file: filePath, displayName: doc.displayName, documentBase64, driveUrl: manifest.driveUrl || base.materialsDriveUrl || '' } };
});

const sent = $input.all();
const failures = sent.filter((item) => item.json?.error || item.json?.message?.includes?.('failed'));
return [{ json: { ...$('Route State').item.json, sentDocuments: sent.length, failedDocuments: failures.length } }];

