const sale = $json;
const route = $('Route State').item.json;
const token = String(sale.mercadoPagoAccessToken || '').trim();
if (!token) throw new Error('MERCADO_PAGO_ACCESS_TOKEN não configurado no app_config.');
const minimum = Number(sale.mercadoPagoMinAmount || 10);
const configured = String(sale.mercadoPagoAmounts || '10.00,14.90,19.90,29.90,49.90')
  .split(',')
  .map((value) => Number(String(value).replace(',', '.').trim()))
  .filter((value) => Number.isFinite(value) && value >= minimum);
const amounts = [...new Set(configured.length ? configured : [10, 14.9, 19.9, 29.9, 49.9])].sort((a, b) => a - b);
const externalReference = 'sale:' + sale.saleId;
const options = [];
for (const amount of amounts) {
  const response = await fetch('https://api.mercadopago.com/checkout/preferences', {
    method: 'POST',
    headers: {
      Authorization: 'Bearer ' + token,
      'Content-Type': 'application/json',
      accept: 'application/json',
    },
    body: JSON.stringify({
      items: [{ title: 'Kit de Matemática - atividades', quantity: 1, unit_price: amount, currency_id: 'BRL' }],
      external_reference: externalReference,
      statement_descriptor: 'KIT MATEMATICA',
      payment_methods: { installments: 1, excluded_payment_types: [{ id: 'ticket' }] },
      metadata: { sale_id: sale.saleId, contact_id: sale.contactId, selected_amount: amount },
    }),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error('Mercado Pago preference failed: ' + response.status + ' ' + JSON.stringify(data));
  options.push({ amount: amount.toFixed(2), id: String(data.id || ''), link: String(data.init_point || data.sandbox_init_point || '') });
}
const paymentLinkText = options.map((option) => 'R$ ' + option.amount.replace('.', ',') + ': ' + option.link).join('\n');
return [{ json: { ...sale, mercadoPagoExternalReference: externalReference, mercadoPagoPaymentOptions: options, mercadoPagoPaymentLink: options[0]?.link || '', paymentLinkText } }];

