const base = $('Find Sale For Name Verification').item.json;
const typedName = String(base.typedPayerName || '').trim();
const minimumAmount = Number(base.mercadoPagoMinAmount || 10);
function normalize(value) {
  return String(value || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
const typedNormalized = normalize(typedName);
const typedTokens = typedNormalized.split(' ').filter((token) => token.length >= 2);
function amountOf(payment) {
  return Number(payment.transaction_amount || payment.transaction_details?.total_paid_amount || payment.transaction_details?.net_received_amount || 0);
}
function approvedDate(payment) {
  return new Date(payment.date_approved || payment.date_created || payment.date_last_updated || 0);
}
function collectNames(value, parentKey = '', names = []) {
  if (!value || typeof value !== 'object') return names;
  for (const [key, child] of Object.entries(value)) {
    const keyName = String(key).toLowerCase();
    if (typeof child === 'string') {
      if (/name|nome|first_name|last_name|long_name|holder_name|cardholder/.test(keyName)) names.push(child);
    } else if (child && typeof child === 'object') {
      collectNames(child, keyName, names);
    }
  }
  return names;
}
function candidateNames(payment) {
  const names = new Set();
  const payer = payment.payer || {};
  const extraPayer = payment.additional_info?.payer || {};
  const bankPayer = payment.point_of_interaction?.transaction_data?.bank_info?.payer || {};
  for (const pair of [
    [payer.first_name, payer.last_name],
    [extraPayer.first_name, extraPayer.last_name],
    [bankPayer.long_name, ''],
    [payment.card?.cardholder?.name, ''],
  ]) {
    const name = pair.filter(Boolean).join(' ').trim();
    if (name) names.add(name);
  }
  collectNames(payment).forEach((name) => names.add(name));
  return [...names].filter((name) => normalize(name).split(' ').length >= 1);
}
function scoreName(candidate) {
  const normalized = normalize(candidate);
  if (!normalized || typedTokens.length < 2) return 0;
  const hits = typedTokens.filter((token) => normalized.includes(token)).length;
  const first = typedTokens[0];
  const last = typedTokens[typedTokens.length - 1];
  const firstLastHit = normalized.includes(first) && normalized.includes(last);
  return Math.max(hits / typedTokens.length, firstLastHit ? 0.82 : 0);
}
const recentLimit = Date.now() - 48 * 60 * 60 * 1000;
const saleCreatedAt = new Date(base.saleCreatedAt || 0);
const saleWindowStart = Number.isNaN(saleCreatedAt.getTime()) ? recentLimit : Math.max(saleCreatedAt.getTime() - 5 * 60 * 1000, recentLimit);
const payments = Array.isArray($json.results) ? $json.results : [];
const validPayments = [];
let best = null;
for (const payment of payments) {
  const amount = amountOf(payment);
  const date = approvedDate(payment);
  if (payment.status !== 'approved') continue;
  if (String(payment.payment_method_id || payment.payment_method?.id || '').toLowerCase() !== 'pix') continue;
  if (!(amount >= minimumAmount)) continue;
  if (!(date instanceof Date) || Number.isNaN(date.getTime()) || date.getTime() < saleWindowStart) continue;
  validPayments.push({ payment, amount, date: date.toISOString() });
  for (const name of candidateNames(payment)) {
    const score = scoreName(name);
    if (!best || score > best.confidence) {
      best = { payment, matchedName: name, confidence: score, amount, date: date.toISOString(), matchMode: 'name' };
    }
  }
}
let matched = Boolean(best && best.confidence >= 0.7);
let matchMode = matched ? 'name' : 'none';
if (!matched && validPayments.length === 1) {
  const only = validPayments[0];
  best = { ...only, matchedName: '', confidence: 0.6, matchMode: 'single_recent_pix' };
  matched = true;
  matchMode = 'single_recent_pix';
}
return [{ json: {
  ...base,
  typedPayerName: typedName,
  matched,
  invalidName: typedTokens.length < 2,
  confidence: best ? Number(best.confidence.toFixed(2)) : 0,
  matchMode,
  candidatePaymentCount: validPayments.length,
  matchedPaymentId: best?.payment?.id ? String(best.payment.id) : '',
  matchedAmount: best ? best.amount : 0,
  matchedName: best?.matchedName || '',
  matchedPaymentDate: best?.date || '',
  mercadoPagoStatus: matched ? (matchMode === 'name' ? 'possible_name_match' : 'possible_recent_pix_match') : 'name_not_found',
  mercadoPagoStatusDetail: matched ? (matchMode === 'name' ? 'approved_payment_found_by_name' : 'single_recent_approved_pix_found') : (typedTokens.length < 2 ? 'typed_name_too_short' : 'no_recent_approved_payment_match'),
  rawPayment: best?.payment || null,
  mercadoPagoError: $json.error || null,
} }];

